const raw = $input.first().json;
const parts = raw.candidates?.[0]?.content?.parts || [];
const text = parts.map(p => p.text).filter(Boolean).join('').trim();
if (!text) {
  throw new Error('Gemini не вернул текст промпта. Ответ: ' + JSON.stringify(raw));
}
return [{ json: { prompt: text } }];

const item = $input.first().json;
const parts = item.candidates?.[0]?.content?.parts || [];
const imgPart = parts.find(p => p.inlineData && p.inlineData.data);
if (!imgPart) {
  throw new Error('Nano Banana не вернул изображение. Ответ: ' + JSON.stringify(item));
}
const prompt = $('Извлечь текст промпта').item.json.prompt;
return [{
  json: {
    prompt,
    image_base64: imgPart.inlineData.data,
    mime_type: imgPart.inlineData.mimeType || 'image/png'
  }
}];

const raw = $input.first().json;
const parts = raw.candidates?.[0]?.content?.parts || [];
const verdict = parts.map(p => p.text).filter(Boolean).join('').trim() || 'нет ответа от Gemini';
const data = $('Подготовить данные картинки').item.json;
return [{
  json: {
    prompt: data.prompt,
    image_base64: data.image_base64,
    mime_type: data.mime_type,
    verdict
  }
}];

const raw = $input.first().json;
const videoId = raw.data?.video_id;
if (!videoId) {
  throw new Error('Heygen не вернул video_id. Ответ: ' + JSON.stringify(raw));
}
return [{ json: { video_id: videoId } }];

const raw = $input.first().json;
const d = raw.data || {};
const err = raw.error || null;
return [{
  json: {
    status: d.status || 'unknown',
    video_url: d.video_url || null,
    error: err || (d.failure_message ? { code: d.failure_code, message: d.failure_message } : null)
  }
}];
